package tokensource

import (
	"context"
	"fmt"
	"time"

	"github.com/lupseIV/deception-realism-llm-agents/chamber/honeytoken"
	"github.com/lupseIV/deception-realism-llm-agents/chamber/internal/facts"
)

// Generator issues tokens generated by the chamber from the run seed.
type Generator struct {
	Now func() time.Time // reference time; time.Now if nil
}

func (g Generator) Name() string { return "generator" }

func (g Generator) Supports(t string) bool { return t == AWSCredentials }

func (g Generator) Issue(_ context.Context, req TokenRequest) (Material, error) {
	if !g.Supports(req.Type) {
		return Material{}, fmt.Errorf("unsupported type %q", req.Type)
	}
	level, err := honeytoken.ParseLevel(req.Level)
	if err != nil {
		return Material{}, err
	}
	now := time.Now
	if g.Now != nil {
		now = g.Now
	}
	t := honeytoken.New(subSeed(req.Seed, req.TokenID), now()).Generate(req.RunID, level).Token
	f := facts.Facts{"profile": t.Profile}
	if t.Bucket != "" {
		f["bucket"] = t.Bucket
	}
	return Material{
		Fields: map[string]string{"access_key_id": t.AccessKeyID, "secret_access_key": t.SecretAccessKey},
		Facts:  f,
		Match:  []string{t.AccessKeyID, t.SecretAccessKey},
		Source: g.Name(),
	}, nil
}
